
--체크리스트 템플릿
CREATE TABLE "chk_tmpl" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "step_id" bigint NOT NULL,
  "title" varchar(200) NOT NULL,
  "dscr" text,
  "req_type" varchar(10) NOT NULL,
  "sort_ord" integer NOT NULL,
  "del_yn" char(1) NOT NULL DEFAULT 'N',
  "del_dt" timestamptz,
  "del_id" bigint,
  "updt_id" bigint NOT NULL,
  "updt_dt" timestamptz NOT NULL,
  "crt_id" bigint NOT NULL,
  "crt_dt" timestamptz NOT NULL
);

COMMENT ON TABLE chk_tmpl IS '체크리스트 템플릿';

COMMENT ON COLUMN "chk_tmpl"."step_id" IS '단계 ID';

COMMENT ON COLUMN "chk_tmpl"."title" IS '템플릿 제목';

COMMENT ON COLUMN "chk_tmpl"."dscr" IS '템플릿 설명';

COMMENT ON COLUMN "chk_tmpl"."req_type" IS 'REQ: 필수 / OPT: 선택';

COMMENT ON COLUMN "chk_tmpl"."sort_ord" IS '정렬순서';

COMMENT ON COLUMN "chk_tmpl"."del_yn" IS '삭제 여부';

COMMENT ON COLUMN "chk_tmpl"."del_dt" IS '삭제일시';

COMMENT ON COLUMN "chk_tmpl"."del_id" IS '삭제자 ID. 미삭제 시 NULL';

COMMENT ON COLUMN "chk_tmpl"."updt_id" IS '수정자 ID';

COMMENT ON COLUMN "chk_tmpl"."updt_dt" IS '수정일시';

COMMENT ON COLUMN "chk_tmpl"."crt_id" IS '생성자 ID';

COMMENT ON COLUMN "chk_tmpl"."crt_dt" IS '생성 일시';

--사용자별 체크리스트
CREATE TABLE "user_chk" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "tmpl_id" bigint,
  "step_id" bigint NOT NULL,
  "title" varchar(200) NOT NULL,
  "dscr" text,
  "sort_ord" integer NOT NULL,
  "cmplt_yn" char(1) NOT NULL DEFAULT 'N',
  "cmplt_dt" timestamptz,
  "hidn_yn" char(1) NOT NULL DEFAULT 'N',
  "del_yn" char(1) NOT NULL DEFAULT 'N',
  "del_dt" timestamptz,
  "del_id" bigint,
  "updt_id" bigint NOT NULL,
  "updt_dt" timestamptz NOT NULL,
  "crt_id" bigint NOT NULL,
  "crt_dt" timestamptz NOT NULL
);

COMMENT ON TABLE user_chk IS '사용자별 체크리스트';

COMMENT ON COLUMN "user_chk"."user_id" IS '회원 ID';

COMMENT ON COLUMN "user_chk"."tmpl_id" IS '템플릿ID, 직접 추가한 항목은 NULL';

COMMENT ON COLUMN "user_chk"."step_id" IS '현재 속한 단계 ID';

COMMENT ON COLUMN "user_chk"."title" IS '항목명';

COMMENT ON COLUMN "user_chk"."dscr" IS '항목의 설명';

COMMENT ON COLUMN "user_chk"."sort_ord" IS '정렬순서';

COMMENT ON COLUMN "user_chk"."cmplt_yn" IS '완료 여부';

COMMENT ON COLUMN "user_chk"."cmplt_dt" IS '완료 시간. 미완료 시 NULL';

COMMENT ON COLUMN "user_chk"."hidn_yn" IS '숨김 여부';

COMMENT ON COLUMN "user_chk"."del_yn" IS '삭제 여부';

COMMENT ON COLUMN "user_chk"."del_dt" IS '삭제일시';

COMMENT ON COLUMN "user_chk"."del_id" IS '삭제자 ID. 미삭제 시 NULL';

COMMENT ON COLUMN "user_chk"."updt_id" IS '수정자 ID';

COMMENT ON COLUMN "user_chk"."updt_dt" IS '수정일시';

COMMENT ON COLUMN "user_chk"."crt_id" IS '생성자 ID';

COMMENT ON COLUMN "user_chk"."crt_dt" IS '생성일시';

--회원
CREATE TABLE "user" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "provider" varchar(10) NOT NULL,
  "login_id" varchar(255) NOT NULL,
  "pwd_hash" varchar(255),
  "email" varchar(255),
  "nickname" varchar(50),
  "role" varchar(10) NOT NULL DEFAULT 'USER',
  "del_yn" char(1) NOT NULL DEFAULT 'N',
  "del_dt" timestamptz,
  "del_id" bigint,
  "updt_id" bigint NOT NULL,
  "updt_dt" timestamptz NOT NULL,
  "crt_id" bigint NOT NULL,
  "crt_dt" timestamptz NOT NULL
);
COMMENT ON TABLE "user" IS '회원';

COMMENT ON COLUMN "user"."provider" IS 'LOCAL / GOOGLE / KAKAO / NAVER';

COMMENT ON COLUMN "user"."login_id" IS 'LOCAL: 로그인 이메일 / 소셜: 서비스 사용자 고유 ID';

COMMENT ON COLUMN "user"."pwd_hash" IS 'LOCAL 가입 시 필수. 소셜 가입은 NULL';

COMMENT ON COLUMN "user"."email" IS '소셜에서 제공되지 않으면 NULL';

COMMENT ON COLUMN "user"."nickname" IS '닉네임';

COMMENT ON COLUMN "user"."role" IS 'USER / ADMIN';

COMMENT ON COLUMN "user"."del_yn" IS '삭제(탈퇴) 여부';

COMMENT ON COLUMN "user"."del_dt" IS '삭제일시';

COMMENT ON COLUMN "user"."del_id" IS '삭제자 ID. 미삭제 시 NULL';

COMMENT ON COLUMN "user"."updt_id" IS '수정자 ID';

COMMENT ON COLUMN "user"."updt_dt" IS '수정일시';

COMMENT ON COLUMN "user"."crt_id" IS '생성자 ID';

COMMENT ON COLUMN "user"."crt_dt" IS '생성일시';

CREATE UNIQUE INDEX ON "user" ("provider", "login_id");

ALTER TABLE "chk_tmpl" ADD FOREIGN KEY ("step_id") REFERENCES "chk_step" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "user_chk" ADD FOREIGN KEY ("user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "user_chk" ADD FOREIGN KEY ("tmpl_id") REFERENCES "chk_tmpl" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "user_chk" ADD FOREIGN KEY ("step_id") REFERENCES "chk_step" ("id") DEFERRABLE INITIALLY IMMEDIATE;
